"use client"

import type React from "react"
import { useState } from "react"
import { useRouter } from "next/navigation"
import { useAuth } from "@/context/AuthContext"

export function LoginForm() {
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [rememberMe, setRememberMe] = useState(false)
  const [error, setError] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const { login } = useAuth()
  const router = useRouter()

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError("")
    setIsLoading(true)

    try {
      await login(email, password)
      router.push("/dashboard")
    } catch (err) {
      setError(err instanceof Error ? err.message : "Login failed")
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="w-full" style={{ width: "576px" }}>
      {/* Card Container - 576x304 with gap: 20 */}
      <div className="rounded-lg border border-gray-300 bg-white p-5" style={{ gap: "20px" }}>
        {/* Heading & Helper Text - 576x25 with gap: 10px */}
        <div className="mb-5" style={{ gap: "10px" }}>
          <h2
            className="text-base font-semibold text-gray-900"
            style={{ fontFamily: "Inter", fontWeight: 600, fontSize: "16px", lineHeight: "150%" }}
          >
            Welcome back
          </h2>
        </div>

        {/* Inputs Field Container - 576x162 with gap: 20 */}
        <div className="space-y-5">
          {/* Email Input Field - 576x71 with gap: 8 */}
          <div style={{ gap: "8px" }}>
            {/* Label - 576x21 */}
            <label
              htmlFor="email"
              className="block text-sm font-medium text-gray-900 mb-2"
              style={{
                fontFamily: "Inter",
                fontWeight: 500,
                fontSize: "14px",
                lineHeight: "150%",
                letterSpacing: "0%",
              }}
            >
              Email
            </label>
            {/* Input - 576x42 */}
            <input
              id="email"
              type="email"
              placeholder="name@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="w-full rounded-lg border border-gray-300 bg-gray-50 px-1 py-0.75 text-sm font-normal text-gray-500 placeholder-gray-500 focus:outline-none focus:border-transparent"
              style={{
                fontFamily: "Inter",
                fontWeight: 400,
                fontSize: "14px",
                lineHeight: "125%",
                letterSpacing: "0%",
                verticalAlign: "middle",
                padding: "3px 4px",
                boxShadow: "0 0 0 2px #1c64f2",
              }}
              onFocus={(e) => {
                e.currentTarget.style.boxShadow = "0 0 0 2px #1c64f2"
              }}
              onBlur={(e) => {
                e.currentTarget.style.boxShadow = "none"
              }}
            />
          </div>

          {/* Password Input Field - 576x71 with gap: 8 */}
          <div style={{ gap: "8px" }}>
            {/* Label - 576x21 */}
            <label
              htmlFor="password"
              className="block text-sm font-medium text-gray-900 mb-2"
              style={{
                fontFamily: "Inter",
                fontWeight: 500,
                fontSize: "14px",
                lineHeight: "150%",
                letterSpacing: "0%",
              }}
            >
              Password
            </label>
            {/* Input - 576x42 */}
            <input
              id="password"
              type="password"
              placeholder="••••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="w-full rounded-lg border border-gray-300 bg-gray-50 px-1 py-0.75 text-sm font-normal text-gray-500 placeholder-gray-500 focus:outline-none focus:border-transparent"
              style={{
                fontFamily: "Inter",
                fontWeight: 400,
                fontSize: "14px",
                lineHeight: "125%",
                letterSpacing: "0%",
                verticalAlign: "middle",
                padding: "3px 4px",
              }}
              onFocus={(e) => {
                e.currentTarget.style.boxShadow = "0 0 0 2px #1c64f2"
              }}
              onBlur={(e) => {
                e.currentTarget.style.boxShadow = "none"
              }}
            />
          </div>
        </div>

        {/* Remember Me Checkbox - 576x16 with gap: 8 */}
        <div className="flex items-center gap-2 my-5" style={{ gap: "8px" }}>
          {/* Checkbox - 16x16 */}
          <input
            id="remember"
            type="checkbox"
            checked={rememberMe}
            onChange={(e) => setRememberMe(e.target.checked)}
            className="w-4 h-4 border border-gray-300 rounded bg-gray-50 cursor-pointer"
            style={{
              borderRadius: "4px",
              borderWidth: "0.5px",
              backgroundColor: "#F9FAFB",
              borderColor: "#D1D5DB",
            }}
          />
          {/* Label - 97x14 */}
          <label
            htmlFor="remember"
            className="text-sm font-medium text-gray-500 cursor-pointer"
            style={{
              fontFamily: "Inter",
              fontWeight: 500,
              fontSize: "14px",
              lineHeight: "14px",
              letterSpacing: "0%",
              verticalAlign: "middle",
            }}
          >
            Remember me
          </label>
        </div>

        {/* Error Message */}
        {error && (
          <div className="p-3 text-sm text-red-600 bg-red-50 border border-red-200 rounded-lg mb-5">{error}</div>
        )}

        {/* Button & Helper Text - 576x41 with gap: 16px */}
        <div style={{ gap: "16px" }}>
          {/* Sign In Button - 576x41 */}
          <button
            type="submit"
            disabled={isLoading}
            onClick={handleSubmit}
            className="w-full rounded-lg text-white font-medium transition-colors duration-200"
            style={{
              fontFamily: "Inter",
              fontWeight: 500,
              fontSize: "14px",
              lineHeight: "150%",
              letterSpacing: "0%",
              padding: "2.5px 5px",
              borderRadius: "8px",
              backgroundColor: isLoading ? "#1c64f2" : "#1a56db",
              cursor: isLoading ? "not-allowed" : "pointer",
            }}
            onMouseEnter={(e) => {
              if (!isLoading) e.currentTarget.style.backgroundColor = "#1e40af"
            }}
            onMouseLeave={(e) => {
              if (!isLoading) e.currentTarget.style.backgroundColor = "#1a56db"
            }}
          >
            {isLoading ? "Signing in..." : "Sign in"}
          </button>
        </div>
      </div>
    </div>
  )
}

